#include <stdio.h>
#include <stddef.h>
struct Rec  { char tag; double val; short id; };
struct Rec2 { double val; short id; char tag; };
int main(void) {
    printf("%zu %zu %zu\n", offsetof(struct Rec, val),
           offsetof(struct Rec, id), sizeof(struct Rec));
    printf("%zu %zu\n", offsetof(struct Rec2, tag), sizeof(struct Rec2));
    return 0;
}

#include <stdio.h>
enum Kind { INT, REAL };
struct Val {
    enum Kind k;
    union { int i; double d; } u;   /* one of the two at a time */
};
void show(struct Val v) {
    if (v.k == INT) printf("int %d\n", v.u.i);
    else            printf("real %.2f\n", v.u.d);
}
int main(void) {
    struct Val a = {INT, {.i = 42}}, b = {REAL, {.d = 0.5}};
    show(a); show(b); printf("%zu\n", sizeof(struct Val));
    return 0;
}

questions.questionText:
What does the following fragment print?

struct T { int a, b, c; };
struct T t = {5};
printf("%d %d %d", t.a, t.b, t.c);

What does the following fragment print?

struct T { int a, b, c; };
struct T t = {.c = 3, .a = 1};
printf("%d %d %d", t.a, t.b, t.c);

What does the following fragment print?

struct T { int a, b, c, d; };
struct T t = {.b = 7, 8};
printf("%d %d %d %d", t.a, t.b, t.c, t.d);

What does the following fragment print?

struct In { int x, y; };
struct Out { int a; struct In in; int b; };
struct Out o = {1, {2}, 3};
printf("%d %d %d %d", o.a, o.in.x, o.in.y, o.b);

What does the following fragment print? (<string.h> is included.)

struct S { char name[10]; int age; };
struct S s = {"Ram", 20};
printf("%zu %zu", sizeof(s.name), strlen(s.name));

What does the following fragment print?

struct P { int x; } s = {5};
int y = ++s.x * 2;
printf("%d %d", s.x, y);

What does the following fragment print?

struct Date { int d, m, y; };
struct Emp { int id; struct Date join; };
struct Emp e = {7, {1, 4, 2020}};
printf("%d-%d", e.join.m, e.id);

What does the following fragment print?

struct In { int v; };
struct Out { struct In a, b; };
struct Out o = {{1}, {2}};
o.b = o.a;
o.a.v = 9;
printf("%d %d", o.a.v, o.b.v);

On a typical 64-bit compiler with default alignment (char 1 byte, int 4 bytes and 4-byte aligned), what does this fragment print?

struct A { char c; int i; };
struct B { char d; struct A a; char e; };
printf("%zu", sizeof(struct B));

On a typical 64-bit compiler with default alignment (int 4 bytes, double 8 bytes), what does this fragment print? (<stddef.h> is included.)

union U { int i; double d; char c; };
printf("%zu %zu %zu", offsetof(union U, i),
       offsetof(union U, d), offsetof(union U, c));

On a typical 64-bit compiler with default alignment (char 1, int 4, double 8 bytes, each aligned to its own size), what does this fragment print?

struct S { int a; char b; double c; };
union U { int a; char b; double c; };
printf("%zu %zu", sizeof(struct S), sizeof(union U));

On a typical 64-bit compiler with default alignment (char 1 byte, double 8 bytes and 8-byte aligned), what does this fragment print?

struct X { char a; double b; char c; };
struct Y { double b; char a; char c; };
printf("%zu %zu", sizeof(struct X), sizeof(struct Y));

On a typical 64-bit compiler with default alignment (char 1, short 2, int 4 bytes, each aligned to its own size), what does this fragment print? (<stddef.h> is included.)

struct S { char a; int b; char c; short d; };
printf("%zu %zu %zu", offsetof(struct S, b),
       offsetof(struct S, d), sizeof(struct S));

What does the following fragment print?

union U { int i; float f; } u;
u.i = 10;
printf("%d ", u.i);
u.f = 2.5f;
printf("%.1f", u.f);

What does the following fragment print?

struct A { int tag; int x; };
struct B { int tag; double y; };
union U { struct A a; struct B b; } u;
u.a.tag = 2;
u.a.x = 5;
printf("%d", u.b.tag);

C11 allows an anonymous union inside a structure. What does this fragment print?

struct Val {
    int isInt;
    union { int i; double d; };
};
struct Val v[2] = {{1, {.i = 7}}, {0, {.d = 2.5}}};
for (int k = 0; k < 2; k++)
    if (v[k].isInt) printf("[%d]", v[k].i);
    else printf("[%.1f]", v[k].d);

Assume unsigned int is 4 bytes. Which statement about the value printed by this fragment is correct?

union { unsigned int n; unsigned char b[4]; } u;
u.n = 0x01020304;
printf("%d", u.b[0]);

On a typical 64-bit compiler with default alignment (char 1, int 4, double 8 bytes, each aligned to its own size), what does this fragment print?

union U {
    struct { int x; char c; } s;
    double d;
    char arr[13];
};
printf("%zu", sizeof(union U));

What does the following fragment print?

struct { unsigned int v : 3; } b = {0};
for (int i = 0; i < 10; i++)
    b.v++;
printf("%d", b.v);

Assume unsigned int is 32 bits and that a bit field which does not fit in the bits left in the current unsigned int starts a new unsigned int (the usual behaviour). What does this fragment print?

struct B {
    unsigned int a : 20;
    unsigned int b : 20;
    unsigned int c : 12;
};
printf("%zu", sizeof(struct B));

What does the following fragment print?

typedef struct { int v; } Item, *ItemPtr;
Item it = {4};
ItemPtr p = &it;
p->v *= 3;
printf("%d", it.v);

What does the following fragment print?

enum E { A = 3, B, C = 1, D,
         F = B + D };
printf("%d %d %d", B, D, F);

What does the following fragment print?

enum Level { LOW = 1, MID, HIGH };
enum Level l = MID;
switch (l) {
    case LOW:  printf("L");
    case MID:  printf("M");
    case HIGH: printf("H"); break;
    default:   printf("D");
}

What does the following fragment print?

enum { MON, TUE, WED, NDAYS };
int hours[NDAYS] = {8, 6, 7};
printf("%d %d", NDAYS, hours[TUE]);

What does the following fragment print?

struct S { char n[8]; };
struct S a = {"Ram"}, b;
b = a;
b.n[0] = 'P';
printf("%s %s", a.n, b.n);

What does the following fragment print?

char buf[] = "cat";
struct S { char a[4]; char *p; };
struct S x = {"dog", buf}, y;
y = x;
y.a[0] = 'f';
y.p[0] = 'b';
printf("%s %s %s %s", x.a, x.p, y.a, y.p);

What does the following fragment print?

enum Kind { INT, DBL };
struct Num { enum Kind k; union { int i; double d; } v; };
struct Num a = {DBL, {.d = 2.5}}, b = a;
b.k = INT;
b.v.i = 4;
printf("%d %.1f %d", a.k, a.v.d, b.v.i);
